"""Structured self-evolution proposals generated by an LLM.

The proposer never writes to the flow store. It asks the model for a small JSON
operation list, checks the shape, and hands the operations to FlowEvolution for
graph validation and application.
"""

import json
from typing import Any, Dict, List, Optional, Set, Tuple

OPERATIONS = frozenset({
    "add_node", "update_node", "remove_node", "connect", "disconnect", "rename",
})

SYSTEM_PROMPT = (
    "You edit NeuroCore flow graphs. Reply with one JSON object only: "
    '{"operations": [...]}. Use only the allowed operations, node types and tools. '
    "Keep the graph acyclic and preserve existing node ids unless you add or remove a node."
)


class FlowProposerError(ValueError):
    """Raised when the model does not return a usable operation list."""


class FlowProposer:
    """Turn a goal into validated-shape flow operations without applying them."""

    def __init__(self, llm: Any,
                 allowed_node_types: Optional[Set[Tuple[str, str]]] = None,
                 allowed_tools: Optional[Set[str]] = None,
                 max_operations: int = 6):
        self.llm = llm
        self.allowed_node_types = (
            set(allowed_node_types) if allowed_node_types is not None else None
        )
        self.allowed_tools = set(allowed_tools) if allowed_tools is not None else None
        self.max_operations = max_operations

    async def propose(self, flow: Dict[str, Any], goal: str) -> List[Dict[str, Any]]:
        """Ask the model for operations; return them for FlowEvolution to validate."""
        prompt = self._build_prompt(flow, goal)
        try:
            response = await self.llm.chat_completion(
                messages=[
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": prompt},
                ],
                temperature=0.2,
                max_tokens=900,
                response_format={"type": "json_object"},
                raise_errors=True,
            )
        except Exception as exc:
            raise FlowProposerError(f"LLM proposal failed: {exc}") from exc

        payload = self._parse_response(response)
        operations = payload.get("operations")
        if not isinstance(operations, list) or not operations:
            raise FlowProposerError("proposal must contain a non-empty operations list")
        if len(operations) > self.max_operations:
            raise FlowProposerError(
                f"proposal has {len(operations)} operations, max {self.max_operations}"
            )
        for index, operation in enumerate(operations):
            self._validate_operation(index, operation)
        return operations

    def _build_prompt(self, flow: Dict[str, Any], goal: str) -> str:
        nodes = [
            {
                "id": node.get("id"),
                "moduleId": node.get("moduleId"),
                "nodeTypeId": node.get("nodeTypeId"),
                "name": node.get("name", ""),
            }
            for node in flow.get("nodes", [])
        ]
        parts = [
            f"Flow name: {flow.get('name', '')}",
            f"Nodes: {json.dumps(nodes, ensure_ascii=False)}",
            f"Connections: {json.dumps(flow.get('connections', []), ensure_ascii=False)}",
            f"Supported operations: {', '.join(sorted(OPERATIONS))}",
            f"Goal: {goal}",
            f"Return at most {self.max_operations} operations.",
        ]
        if self.allowed_node_types is not None:
            pairs = [f"{module}:{node_type}"
                     for module, node_type in sorted(self.allowed_node_types)]
            parts.append(f"Allowed node types: {', '.join(pairs)}")
        if self.allowed_tools is not None:
            parts.append(f"Allowed tools: {', '.join(sorted(self.allowed_tools))}")
        return "\n".join(parts)

    def _parse_response(self, response: Any) -> Dict[str, Any]:
        if not isinstance(response, dict):
            raise FlowProposerError("LLM response is not an object")
        choices = response.get("choices")
        if not isinstance(choices, list) or not choices:
            raise FlowProposerError("LLM response has no choices")
        message = choices[0].get("message") if isinstance(choices[0], dict) else None
        content = message.get("content") if isinstance(message, dict) else None
        if isinstance(content, list):
            content = "".join(
                part.get("text", "") for part in content if isinstance(part, dict)
            )
        if not isinstance(content, str) or not content.strip():
            raise FlowProposerError("LLM response has no content")
        text = content.strip()
        if text.startswith("```"):
            text = text.split("\n", 1)[1] if "\n" in text else ""
            if text.rstrip().endswith("```"):
                text = text.rstrip()[:-3]
            text = text.strip()
        try:
            payload = json.loads(text)
        except json.JSONDecodeError as exc:
            raise FlowProposerError(f"proposal is not valid JSON: {exc}") from exc
        if not isinstance(payload, dict):
            raise FlowProposerError("proposal JSON must be an object")
        return payload

    def _validate_operation(self, index: int, operation: Any) -> None:
        if not isinstance(operation, dict):
            raise FlowProposerError(f"operation {index} must be an object")
        kind = operation.get("op")
        if kind not in OPERATIONS:
            raise FlowProposerError(f"operation {index} has unknown op '{kind}'")
        if kind == "add_node":
            node = operation.get("node")
            if not isinstance(node, dict):
                raise FlowProposerError(f"operation {index} add_node needs a node object")
            self._check_node(index, node)
        elif kind == "update_node":
            if not isinstance(operation.get("node_id"), str):
                raise FlowProposerError(f"operation {index} needs node_id")
            if not isinstance(operation.get("changes"), dict):
                raise FlowProposerError(f"operation {index} needs changes")
        elif kind in {"remove_node"}:
            if not isinstance(operation.get("node_id"), str):
                raise FlowProposerError(f"operation {index} needs node_id")
        elif kind in {"connect", "disconnect"}:
            if not isinstance(operation.get("from"), str) or not isinstance(
                    operation.get("to"), str):
                raise FlowProposerError(f"operation {index} needs from and to")
        elif kind == "rename":
            if not isinstance(operation.get("name"), str) or not operation["name"].strip():
                raise FlowProposerError(f"operation {index} needs a name")

    def _check_node(self, index: int, node: Dict[str, Any]) -> None:
        module_id = node.get("moduleId")
        node_type = node.get("nodeTypeId")
        if not isinstance(module_id, str) or not isinstance(node_type, str):
            raise FlowProposerError(
                f"operation {index} add_node needs moduleId and nodeTypeId"
            )
        if (self.allowed_node_types is not None
                and (module_id, node_type) not in self.allowed_node_types):
            raise FlowProposerError(
                f"operation {index} uses disallowed node type {module_id}:{node_type}"
            )
